questionText:
Voici un extrait de code pour l'upload d'avatar. Quelle fonction est manquante pour le traitement de l'image sélectionnée ?

<pre style='background:#2d2d2d; color:#f8f8f2; padding:8px; border-radius:4px;'>
const pickImage = async () => {
  const result = await ImagePicker.launchImageLibraryAsync({
    mediaTypes: ImagePicker.MediaTypeOptions.Images,
    allowsEditing: true,
    aspect: [1, 1],
    quality: 0.8,
  });

  if (!result.canceled) {
    // Fonction manquante ici
    await uploadAvatar(result.assets[0].uri);
  }
};
</pre>
